package org.springframework.samples.petclinic.service;

/**
 * Thrown when an attempt is made to create an {@code Owner} whose normalized telephone number is
 * already used by another owner. Enforcing it in the service layer keeps the uniqueness invariant
 * in one place regardless of which caller initiates the create; the REST layer maps this to a
 * {@code 409 Conflict}.
 */
public class DuplicateTelephoneException extends RuntimeException {

    public DuplicateTelephoneException(String telephone) {
        super("An owner with telephone '" + telephone + "' already exists");
    }

}

}

/**
 * Handles {@link DuplicateTelephoneException}, raised by the service layer when a new owner's normalized
 * telephone is already used by another owner, by returning a 409 Conflict status.
 *
 * @param e The {@link DuplicateTelephoneException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
 */
@ExceptionHandler(DuplicateTelephoneException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
    logger.warn("Duplicate telephone at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.CONFLICT;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

/**
 * Handles {@link DuplicateHouseholdException}, raised by the service layer when a new owner shares
 * the same last name and address as an existing owner and the request did not opt in via
 * {@code sharesHousehold}, by returning a 409 Conflict status.
 *
 * @param e The {@link DuplicateHouseholdException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
 */
@ExceptionHandler(DuplicateHouseholdException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
    logger.warn("Duplicate household at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.CONFLICT;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

/**
 * Handles {@link CityOwnerLimitExceededException}, raised by the service layer when a new owner's
 * city already contains the maximum number of owners, by returning a 409 Conflict status.
 *
 * @param e The {@link CityOwnerLimitExceededException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
 */
@ExceptionHandler(CityOwnerLimitExceededException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
    logger.warn("City owner limit exceeded at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getMessage());
    HttpStatus status = HttpStatus.CONFLICT;
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
    return ResponseEntity.status(status).body(detail);
}

